package app.kinnect.live;
import android.app.*;import android.content.*;import android.graphics.*;import android.graphics.drawable.*;import android.view.*;import android.widget.*;
/** Persistent Kinnect brand and navigation around account feature content. */
final class CommerceChrome {
 static View wrap(Activity a,View content){final float density=a.getResources().getDisplayMetrics().density;int variant=WebTheme.isDark(a)?1:0,card=WebDesign.CARD[variant],muted=WebDesign.MUTED[variant],purple=WebDesign.PURPLE[variant];LinearLayout root=new LinearLayout(a);root.setOrientation(1);if(android.os.Build.VERSION.SDK_INT>=29)root.setForceDarkAllowed(false);root.setBackgroundColor(WebDesign.BG[variant]);root.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(0,i.getSystemWindowInsetTop(),0,i.getSystemWindowInsetBottom());return i;});LinearLayout header=new LinearLayout(a);header.setGravity(Gravity.CENTER_VERTICAL);header.setPadding(dp(12,density),0,dp(10,density),0);header.setBackgroundColor(card);ImageView logo=new ImageView(a);logo.setImageResource(a.getResources().getIdentifier("kinnect_logo","drawable",a.getPackageName()));header.addView(logo,new LinearLayout.LayoutParams(dp(34,density),dp(34,density)));TextView brand=new KinnectText(a);brand.setText("Kinnect");brand.setTextSize(20);brand.setTypeface(null,Typeface.BOLD);brand.setTextColor(purple);brand.setPadding(dp(8,density),0,0,0);brand.setSingleLine(true);header.addView(brand,new LinearLayout.LayoutParams(0,-2,1));logo.setOnClickListener(v->go(a,"feed"));for(String[] item:new String[][]{{"bell","notifications","Thông báo"},{"users-round","friends","Bạn bè"},{"message-square","inbox","Tin nhắn"},{"user-round","account","Tài khoản"}}){ImageView icon=new ImageView(a);android.graphics.drawable.Drawable d=WebIcons.load(a,item[0]);d.setTint(muted);icon.setImageDrawable(d);icon.setPadding(dp(10,density),dp(10,density),dp(10,density),dp(10,density));icon.setContentDescription(I18n.t(item[2]));icon.setOnClickListener(v->go(a,item[1]));header.addView(icon,new LinearLayout.LayoutParams(dp(38,density),dp(44,density)));}root.addView(header,new LinearLayout.LayoutParams(-1,dp(WebDesign.HEADER,density)));root.addView(content,new LinearLayout.LayoutParams(-1,0,1));LinearLayout bottom=new LinearLayout(a);bottom.setBackgroundColor(card);bottom.setGravity(Gravity.CENTER_VERTICAL);for(String[] item:new String[][]{{"feed","house","Bảng tin"},{"discover","compass","Khám phá"},{"create","plus","Tạo"},{"shorts","clapperboard","Video"},{"live","radio","Live"}}){LinearLayout tab=new LinearLayout(a);tab.setOrientation(1);tab.setGravity(Gravity.CENTER);ImageView icon=new ImageView(a);android.graphics.drawable.Drawable d=WebIcons.load(a,item[1]);d.setTint(item[0].equals("create")?Color.WHITE:muted);icon.setImageDrawable(d);if(item[0].equals("create")){GradientDrawable g=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{purple,0xffe748ac});g.setCornerRadius(dp(99,density));icon.setBackground(g);icon.setPadding(dp(10,density),dp(10,density),dp(10,density),dp(10,density));tab.addView(icon,new LinearLayout.LayoutParams(dp(44,density),dp(44,density)));}else{tab.addView(icon,new LinearLayout.LayoutParams(dp(23,density),dp(23,density)));TextView name=new KinnectText(a);name.setText(I18n.t(item[2]));name.setTextSize(10);name.setTextColor(muted);name.setGravity(Gravity.CENTER);tab.addView(name);}tab.setContentDescription(I18n.t(item[2]));tab.setOnClickListener(v->go(a,item[0]));bottom.addView(tab,new LinearLayout.LayoutParams(0,dp(62,density),1));}root.addView(bottom);return root;}
 private static int dp(int n,float density){return Math.round(n*density);}
 private static void go(Activity a,String target){a.startActivity(new Intent(a,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP).putExtra("commerce_destination",target));a.finish();}
}
